// #97 — the CommonJS half of the option-parity probe. Behaviourally identical to
// `parity-esm-dep/index.mjs`; keep them in step. Both are required/imported INSIDE the install
// window so their load-time captures happen under the policy being probed, exactly as a real
// dependency's do.
const { readFileSync } = require("fs");
const { Socket } = require("net");
const path = require("path");

const DATA = path.join(__dirname, "data.txt");

exports.read = () => {
  try {
    return "OK:" + readFileSync(DATA, "utf8").trim();
  } catch (err) {
    return String(err && err.name);
  }
};

exports.socketPrototypeFrozen = () => Object.isFrozen(Socket.prototype);

exports.readDeep = (depth) => {
  const call = depth <= 0 ? exports.read : () => exports.readDeep(depth - 1);
  return call();
};

exports.readEnv = (key) => process.env[key];

exports.fetchProbe = async (url) => {
  try {
    await fetch(url);
    return "OK";
  } catch (err) {
    return String(err && err.name);
  }
};
